@startuml

class Bettor {
  + name : string
  + id : int
}

class Race {
  + raceId : string
  + raceName : string
}

class Runner {
  + runnerId : string
  + horseName : string
}

class Jockey {
  + name : string
  + licenseNumber : string
}

class Bet {
  + betId : string
  + amount : double
  + odds : double
}

Bettor "1" -- "0..*" Bet : places
Race "1" -- "1..*" Runner : contains
Runner "1" -- "1" Jockey : ridden_by
Race "1" -- "0..1" Runner : winner
Bet "0..*" -- "1" Race : refers_to
Bet "0..*" -- "1" Runner : refers_to

@enduml

